$documentId = \Flashpi\Laravel\Tests\Examples\Readme\Context::documentId();
$document = \Flashpi\Laravel\Tests\Examples\Readme\Context::document();

$pdf = Flashpi::documents()->pdf($documentId); // the RIDE, as bytes
